// The bridge of Fees.FeeRule, Fees.FlatFee, Fees.PercentFee (CodeCoreMorph, D-78).
#include "fee_rule.h"

#include "codecoremorph_bridge.hpp"
#include "fee_rule.hpp"

namespace bridge = ccm::bridge;

namespace {

// The C# object's virtual members, which a director calls.
struct FeeRuleCalls {
    fees_FeeRule_fee_fn fee;
    fees_FeeRule_applies_fn applies;
    fees_FeeRule_label_fn label;
};

// What the base calls need of a director, whichever ported class it derives from.
class FeeRuleDirected {
public:
    FeeRuleDirected() = default;
    FeeRuleDirected(const FeeRuleDirected&) = delete;
    FeeRuleDirected& operator=(const FeeRuleDirected&) = delete;
    FeeRuleDirected(FeeRuleDirected&&) = delete;
    FeeRuleDirected& operator=(FeeRuleDirected&&) = delete;
    virtual ~FeeRuleDirected() = default;

    virtual ccm::Decimal base_fee(const ccm::Decimal& amount) const = 0;
    virtual bool base_applies(const ccm::Decimal& amount) const = 0;
    virtual std::string base_label() const = 0;
};

// The native object of a C# class derived from P (FeeRule, FlatFee or PercentFee): each virtual
// member calls the C# object's, so the C++ that calls it (charge, describe, a schedule's total)
// runs the C# override; the base calls run P's own.
template <class P>
class FeeRuleDirector final : public P, public FeeRuleDirected, public bridge::Director {
public:
    template <class... A>
    FeeRuleDirector(bridge::ManagedRef managed, FeeRuleCalls calls, A&&... args)
        : P(std::forward<A>(args)...), bridge::Director(std::move(managed)), calls_(calls) {}

    ccm::Decimal fee(const ccm::Decimal& amount) const override {
        ccm_decimal result{};
        bridge::check_managed(calls_.fee(context(), bridge::dec(amount), &result));
        return bridge::dec(result);
    }

    bool applies(const ccm::Decimal& amount) const override {
        bool result = false;
        bridge::check_managed(calls_.applies(context(), bridge::dec(amount), &result));
        return result;
    }

    std::string label() const override {
        char* result = nullptr;
        bridge::check_managed(calls_.label(context(), &result));
        return bridge::take_str(result);
    }

    ccm::Decimal base_fee(const ccm::Decimal& amount) const override {
        if constexpr (std::is_same_v<P, fees::FeeRule>) {
            // FeeRule.Fee is abstract: no façade's body calls it.
            throw ccm::InvalidOperationException("FeeRule.Fee is abstract");
        } else {
            return P::fee(amount);
        }
    }

    bool base_applies(const ccm::Decimal& amount) const override { return P::applies(amount); }

    std::string base_label() const override { return P::label(); }

private:
    FeeRuleCalls calls_;
};

// FeeRule's protected static members, for the C# classes derived from it.
struct FeeRuleProtected : fees::FeeRule {
    using fees::FeeRule::round;
};

const FeeRuleDirected& directed(const fees_FeeRule* self) {
    const auto* director = dynamic_cast<const FeeRuleDirected*>(bridge::from_handle(self).get());
    if (director == nullptr) {
        throw ccm::InvalidOperationException("a base call on an object no C# class derives from");
    }
    return *director;
}

template <class P, class... A>
void new_director(const bridge::ManagedRef& managed, FeeRuleCalls calls, void** result_director,
                  fees_FeeRule** result, A&&... args) {
    auto director =
        bridge::make_director<FeeRuleDirector<P>>(managed, calls, std::forward<A>(args)...);
    *result_director = static_cast<bridge::Director&>(*director).id();
    *result = bridge::to_handle<fees_FeeRule>(std::shared_ptr<fees::FeeRule>(director));
}

}  // namespace

CCM_HANDLE_EXPORTS(fees_FeeRule)

extern "C" {

CCM_EXPORT ccm_status fees_FeeRule_name(const fees_FeeRule* self, char** result) {
    return bridge::guard([&] { bridge::out_str(result, bridge::from_handle(self)->name()); });
}

CCM_EXPORT ccm_status fees_FeeRule_fee(const fees_FeeRule* self, ccm_decimal amount,
                                       ccm_decimal* result) {
    return bridge::guard(
        [&] { *result = bridge::dec(bridge::from_handle(self)->fee(bridge::dec(amount))); });
}

CCM_EXPORT ccm_status fees_FeeRule_applies(const fees_FeeRule* self, ccm_decimal amount,
                                           bool* result) {
    return bridge::guard(
        [&] { *result = bridge::from_handle(self)->applies(bridge::dec(amount)); });
}

CCM_EXPORT ccm_status fees_FeeRule_label(const fees_FeeRule* self, char** result) {
    return bridge::guard([&] {
        // label is protected: only a C# class derived from FeeRule calls it, through its
        // director's base call; a ported object's façade has no caller.
        bridge::out_str(result, directed(self).base_label());
    });
}

CCM_EXPORT ccm_status fees_FeeRule_charge(const fees_FeeRule* self, ccm_decimal amount,
                                          ccm_decimal* result) {
    return bridge::guard(
        [&] { *result = bridge::dec(bridge::from_handle(self)->charge(bridge::dec(amount))); });
}

CCM_EXPORT ccm_status fees_FeeRule_describe(const fees_FeeRule* self, ccm_decimal amount,
                                            char** result) {
    return bridge::guard([&] {
        bridge::out_str(result, bridge::from_handle(self)->describe(bridge::dec(amount)));
    });
}

CCM_EXPORT ccm_status fees_FeeRule_round(ccm_decimal value, ccm_decimal* result) {
    return bridge::guard(
        [&] { *result = bridge::dec(FeeRuleProtected::round(bridge::dec(value))); });
}

CCM_EXPORT ccm_status fees_FeeRule_kind(const fees_FeeRule* self, int32_t* result) {
    return bridge::guard([&] {
        const fees::FeeRule* rule = bridge::from_handle(self).get();
        if (dynamic_cast<const FeeRuleDirected*>(rule) != nullptr) {
            *result = 2;
        } else if (dynamic_cast<const fees::FlatFee*>(rule) != nullptr) {
            *result = 0;
        } else {
            *result = 1;
        }
    });
}

CCM_EXPORT ccm_status fees_FeeRule_new_director(const char* name, void* context,
                                                ccm_release_fn release, fees_FeeRule_fee_fn fee,
                                                fees_FeeRule_applies_fn applies,
                                                fees_FeeRule_label_fn label,
                                                void** result_director, fees_FeeRule** result) {
    return bridge::guard([&] {
        // First: the context is released however the export ends, the name refused included.
        bridge::ManagedRef managed(context, release);
        new_director<fees::FeeRule>(managed, FeeRuleCalls{fee, applies, label}, result_director,
                                    result, bridge::str(name, "name"));
    });
}

CCM_EXPORT ccm_status fees_FlatFee_new_director(ccm_decimal fee, void* context,
                                                ccm_release_fn release,
                                                fees_FeeRule_fee_fn fee_fn,
                                                fees_FeeRule_applies_fn applies,
                                                fees_FeeRule_label_fn label,
                                                void** result_director, fees_FeeRule** result) {
    return bridge::guard([&] {
        bridge::ManagedRef managed(context, release);
        new_director<fees::FlatFee>(managed, FeeRuleCalls{fee_fn, applies, label},
                                    result_director, result, bridge::dec(fee));
    });
}

CCM_EXPORT ccm_status fees_PercentFee_new_director(ccm_decimal percent, ccm_decimal minimum,
                                                   void* context, ccm_release_fn release,
                                                   fees_FeeRule_fee_fn fee,
                                                   fees_FeeRule_applies_fn applies,
                                                   fees_FeeRule_label_fn label,
                                                   void** result_director, fees_FeeRule** result) {
    return bridge::guard([&] {
        bridge::ManagedRef managed(context, release);
        new_director<fees::PercentFee>(managed, FeeRuleCalls{fee, applies, label},
                                       result_director, result, bridge::dec(percent),
                                       bridge::dec(minimum));
    });
}

CCM_EXPORT ccm_status fees_FeeRule_base_fee(const fees_FeeRule* self, ccm_decimal amount,
                                            ccm_decimal* result) {
    return bridge::guard(
        [&] { *result = bridge::dec(directed(self).base_fee(bridge::dec(amount))); });
}

CCM_EXPORT ccm_status fees_FeeRule_base_applies(const fees_FeeRule* self, ccm_decimal amount,
                                                bool* result) {
    return bridge::guard([&] { *result = directed(self).base_applies(bridge::dec(amount)); });
}

CCM_EXPORT ccm_status fees_FeeRule_base_label(const fees_FeeRule* self, char** result) {
    return bridge::guard([&] { bridge::out_str(result, directed(self).base_label()); });
}

CCM_EXPORT ccm_status fees_FlatFee_new(ccm_decimal fee, fees_FeeRule** result) {
    return bridge::guard([&] {
        *result = bridge::to_handle<fees_FeeRule>(
            std::shared_ptr<fees::FeeRule>(std::make_shared<fees::FlatFee>(bridge::dec(fee))));
    });
}

CCM_EXPORT ccm_status fees_FlatFee_amount(const fees_FeeRule* self, ccm_decimal* result) {
    return bridge::guard([&] {
        const auto* flat = dynamic_cast<const fees::FlatFee*>(bridge::from_handle(self).get());
        if (flat == nullptr) throw ccm::InvalidOperationException("not a FlatFee");
        *result = bridge::dec(flat->amount());
    });
}

CCM_EXPORT ccm_status fees_PercentFee_new(ccm_decimal percent, ccm_decimal minimum,
                                          fees_FeeRule** result) {
    return bridge::guard([&] {
        *result = bridge::to_handle<fees_FeeRule>(std::shared_ptr<fees::FeeRule>(
            std::make_shared<fees::PercentFee>(bridge::dec(percent), bridge::dec(minimum))));
    });
}

}  // extern "C"

