// The C++ of Fees.FeeRule, Fees.FlatFee, Fees.PercentFee, ported from C# (CodeCoreMorph, D-78).
#include "fee_rule.hpp"

#include <utility>

#include "codecoremorph_exceptions.hpp"

namespace fees {

namespace {
// Math.Round(value, 2, MidpointRounding.AwayFromZero); ccm::Decimal's round, found by its
// argument (FeeRule::round hides it inside the class).
ccm::Decimal cents(const ccm::Decimal& value) { return round(value, 2, true); }
}  // namespace

FeeRule::FeeRule(std::string name) : name_(std::move(name)) {}

bool FeeRule::applies(const ccm::Decimal& amount) const { return amount > ccm::Decimal(); }

ccm::Decimal FeeRule::charge(const ccm::Decimal& amount) const {
    return applies(amount) ? round(fee(amount)) : ccm::Decimal();
}

std::string FeeRule::describe(const ccm::Decimal& amount) const {
    return label() + ": " + charge(amount).to_string();
}

std::string FeeRule::label() const { return name_; }

ccm::Decimal FeeRule::round(const ccm::Decimal& value) { return cents(value); }

FlatFee::FlatFee(const ccm::Decimal& fee) : FeeRule("flat"), fee_(fee) {
    if (fee < ccm::Decimal()) {
        throw ccm::ArgumentOutOfRangeException("fee", "a fee can't be negative");
    }
}

ccm::Decimal FlatFee::fee(const ccm::Decimal& /*amount*/) const { return fee_; }

PercentFee::PercentFee(const ccm::Decimal& percent, const ccm::Decimal& minimum)
    : FeeRule("percent"), percent_(percent), minimum_(minimum) {}

ccm::Decimal PercentFee::fee(const ccm::Decimal& amount) const {
    return amount * percent_ / ccm::Decimal(100);
}

bool PercentFee::applies(const ccm::Decimal& amount) const {
    return FeeRule::applies(amount) && amount >= minimum_;
}

std::string PercentFee::label() const { return name() + " " + percent_.to_string() + "%"; }

}  // namespace fees

// The C++ of Fees.FeeRule, Fees.FlatFee, Fees.PercentFee, ported from C# (CodeCoreMorph, D-78).
#ifndef FEES_FEE_RULE_HPP
#define FEES_FEE_RULE_HPP

#include <string>

#include "codecoremorph_decimal.hpp"

namespace fees {

// A rule that charges a fee on an amount.
class FeeRule {
public:
    virtual ~FeeRule() = default;
    FeeRule(const FeeRule&) = delete;
    FeeRule& operator=(const FeeRule&) = delete;
    FeeRule(FeeRule&&) = delete;
    FeeRule& operator=(FeeRule&&) = delete;

    // The rule's name in a schedule.
    const std::string& name() const { return name_; }
    // The fee before rounding.
    virtual ccm::Decimal fee(const ccm::Decimal& amount) const = 0;
    // Whether the rule charges anything on the amount.
    virtual bool applies(const ccm::Decimal& amount) const;
    // The fee charged: rounded to cents, zero where the rule doesn't apply.
    ccm::Decimal charge(const ccm::Decimal& amount) const;
    // A line of a report: the rule's label and its charge.
    std::string describe(const ccm::Decimal& amount) const;

protected:
    // A std::string is never null: the bridge throws ArgumentNullException ("name").
    explicit FeeRule(std::string name);
    // The rule's label in a report.
    virtual std::string label() const;
    // Rounds to cents, half away from zero.
    static ccm::Decimal round(const ccm::Decimal& value);

private:
    std::string name_;
};

// The same fee on every amount.
class FlatFee : public FeeRule {
public:
    // Throws ArgumentOutOfRangeException ("fee") for a negative fee.
    explicit FlatFee(const ccm::Decimal& fee);
    const ccm::Decimal& amount() const { return fee_; }
    ccm::Decimal fee(const ccm::Decimal& amount) const override;

private:
    ccm::Decimal fee_;
};

// A percentage of the amount, from a minimum amount up.
class PercentFee : public FeeRule {
public:
    PercentFee(const ccm::Decimal& percent, const ccm::Decimal& minimum);
    ccm::Decimal fee(const ccm::Decimal& amount) const override;
    bool applies(const ccm::Decimal& amount) const override;

protected:
    std::string label() const override;

private:
    ccm::Decimal percent_;
    ccm::Decimal minimum_;
};

}  // namespace fees

#endif

