using System;
using CodeCoreMorph.Interop;

namespace Fees
{
    /// <summary>A rule that charges a fee on an amount.</summary>
    public abstract class FeeRule
    {
        // A C# class derived from this one runs on a director (D-87), which its handle carries.
        internal fees_FeeRuleHandle Handle;

        internal static readonly fees_FeeRule_fee_fn FeeCall = CallFee;
        internal static readonly fees_FeeRule_applies_fn AppliesCall = CallApplies;
        internal static readonly fees_FeeRule_label_fn LabelCall = CallLabel;

        protected FeeRule(string name)
        {
            // FlatFee and PercentFee attach their own handle; only a C# class derived from FeeRule
            // calls this constructor, so the object is a director's.
            CcmDirector director = CcmDirector.Create(this);
            IntPtr native;
            fees_FeeRuleHandle handle;
            CcmInterop.Check(CcmNative.fees_FeeRule_new_director(
                name, director.Context, CcmDirectors.Release, FeeCall, AppliesCall, LabelCall,
                out native, out handle));
            Attach(handle, director, native);
        }

        // For FlatFee's and PercentFee's façades, which attach their handle.
        internal FeeRule()
        {
        }

        internal void Attach(fees_FeeRuleHandle handle, CcmDirector director, IntPtr native)
        {
            Handle = handle;
            if (director != null)
            {
                director.Attach(handle, native);
            }
            CcmObjects.Register(handle.Key, this);
        }

        /// <summary>The rule's name in a schedule.</summary>
        public string Name
        {
            get
            {
                IntPtr result;
                CcmInterop.Check(CcmNative.fees_FeeRule_name(Handle, out result));
                return CcmInterop.TakeString(result);
            }
        }

        /// <summary>The fee before rounding.</summary>
        public abstract decimal Fee(decimal amount);

        /// <summary>Whether the rule charges anything on the amount.</summary>
        public virtual bool Applies(decimal amount)
        {
            bool result;
            CcmInterop.Check(Handle.Director != null
                ? CcmNative.fees_FeeRule_base_applies(Handle, CcmDecimal.From(amount), out result)
                : CcmNative.fees_FeeRule_applies(Handle, CcmDecimal.From(amount), out result));
            return result;
        }

        /// <summary>The fee charged: rounded to cents, zero where the rule doesn't apply.</summary>
        public decimal Charge(decimal amount)
        {
            CcmDecimal result;
            CcmInterop.Check(CcmNative.fees_FeeRule_charge(Handle, CcmDecimal.From(amount), out result));
            return result.ToDecimal();
        }

        /// <summary>A line of a report: the rule's label and its charge.</summary>
        public string Describe(decimal amount)
        {
            IntPtr result;
            CcmInterop.Check(CcmNative.fees_FeeRule_describe(Handle, CcmDecimal.From(amount), out result));
            return CcmInterop.TakeString(result);
        }

        /// <summary>The rule's label in a report.</summary>
        protected virtual string Label()
        {
            IntPtr result;
            CcmInterop.Check(Handle.Director != null
                ? CcmNative.fees_FeeRule_base_label(Handle, out result)
                : CcmNative.fees_FeeRule_label(Handle, out result));
            return CcmInterop.TakeString(result);
        }

        /// <summary>Rounds to cents, half away from zero.</summary>
        protected static decimal Round(decimal value)
        {
            CcmDecimal result;
            CcmInterop.Check(CcmNative.fees_FeeRule_round(CcmDecimal.From(value), out result));
            return result.ToDecimal();
        }

        internal static fees_FeeRuleHandle HandleOf(FeeRule rule)
        {
            return rule == null ? fees_FeeRuleHandle.Null : rule.Handle;
        }

        internal static FeeRule FromHandle(fees_FeeRuleHandle handle)
        {
            return CcmObjects.Wrap(handle, h =>
            {
                int kind;
                CcmInterop.Check(CcmNative.fees_FeeRule_kind(h, out kind));
                switch (kind)
                {
                    case 0:
                        return (FeeRule)new FlatFee(h);
                    case 1:
                        return new PercentFee(h);
                    default:
                        // A director's C# object is held while native code holds the director.
                        throw new InvalidOperationException("a C# rule came back after it was collected");
                }
            });
        }

        // The C# object's virtual members, called by its director.
        private static int CallFee(IntPtr context, CcmDecimal amount, out CcmDecimal result)
        {
            return CcmInterop.Callback(
                () => CcmDecimal.From(CcmDirectors.Target<FeeRule>(context).Fee(amount.ToDecimal())),
                out result);
        }

        private static int CallApplies(IntPtr context, CcmDecimal amount, out bool result)
        {
            return CcmInterop.Callback(
