TEST(ScheduleTests, FindGivesBackTheSameObject) {
    Schedule schedule;
    auto capped = std::make_shared<CappedFee>("mine", d("0.1"), d("5"));
    auto flat = std::make_shared<FlatFee>(d("1"));
    schedule.add(capped);
    schedule.add(flat);
    EXPECT_EQ(schedule.find("mine"), capped);
    EXPECT_EQ(schedule.find("flat"), flat);
    EXPECT_EQ(schedule.find("none"), nullptr);
}

TEST(ScheduleTests, AddRefusesNull) {
    auto e = thrown<ccm::ArgumentNullException>([] { Schedule().add(nullptr); });
    ASSERT_NE(e, nullptr);
    EXPECT_EQ(e->param_name(), "rule");
}

TEST(ScheduleTests, AnExceptionFromAnOverrideReachesTheCaller) {
    Schedule schedule;
    schedule.add(std::make_shared<FlatFee>(d("1")));
    schedule.add(std::make_shared<FailingFee>());
    auto e = thrown<NoFeeToday>([&] { schedule.total(d("10")); });
    ASSERT_NE(e, nullptr);
    EXPECT_STREQ(e->what(), "no fee today");
}

TEST(ScheduleTests, ARuleOnlyTheScheduleHoldsStaysAlive) {
    Schedule schedule;
    add_capped(schedule, "kept");
    EXPECT_EQ(schedule.total(d("10")), d("1.00"));
    auto found = std::dynamic_pointer_cast<CappedFee>(schedule.find("kept"));
    ASSERT_NE(found, nullptr);
    EXPECT_EQ(found->calls(), 1);
}

TEST(ScheduleTests, ARuleNothingHoldsIsCollected) {
    std::weak_ptr<FeeRule> rule = unheld();
    EXPECT_TRUE(rule.expired());
}

TEST(ScheduleTests, ARemovedRuleIsCollected) {
    Schedule schedule;
    std::weak_ptr<FeeRule> rule = add_capped(schedule, "gone");
    EXPECT_FALSE(rule.expired());
    EXPECT_TRUE(schedule.remove("gone"));
    EXPECT_FALSE(schedule.remove("gone"));
    EXPECT_TRUE(rule.expired());
    EXPECT_EQ(schedule.count(), 0);
}
